from src.jobs.queue import enqueue

# Days after the failed charge on which to retry (finance policy FP-12).
RETRY_DAYS = (1, 3, 7, 14)


def schedule_retries(invoice):
    """Plan the payment retries for an invoice whose charge just failed, and enqueue each one."""
    jobs = []
    for attempt, day in enumerate(RETRY_DAYS, start=1):
        jobs.append(
            enqueue(
                "invoices.retry_payment",
                {
                    "invoice_id": invoice.id,
                    "attempt": attempt,
                    "days_after_failure": day,
                    "final": attempt == len(RETRY_DAYS),
                },
                dedupe_key=f"dunning:{invoice.id}:{attempt}",
            )
        )
    return jobs
